from pathlib import Path

ROOT=Path(__file__).resolve().parent

def between(path,start,end,new):
 p=ROOT/path; s=p.read_text(encoding='utf-8'); i=s.find(start); j=s.find(end,i+len(start))
 if i<0 or j<0: raise RuntimeError(f'v1.4 patch limits not found: {path}')
 p.write_text(s[:i]+new.rstrip()+'\n\n'+s[j:],encoding='utf-8')

# Version and portfolio policy: dynamic 2-5 bots, up to 60% only when conviction supports it.
p=ROOT/'app/config.py'; s=p.read_text(encoding='utf-8')
s=s.replace('APP_VERSION = "1.3"','APP_VERSION = "1.4"').replace('APP_VERSION = "1.1"','APP_VERSION = "1.4"')
s=s.replace('max_recommended_bots: int = 4','max_recommended_bots: int = 5')
s=s.replace('max_single_bot_pct: float = 0.50','max_single_bot_pct: float = 0.60').replace('max_asset_exposure_pct: float = 0.50','max_asset_exposure_pct: float = 0.60')
s=s.replace('continuity_bonus: float = 5.0','continuity_bonus: float = 2.5')
p.write_text(s,encoding='utf-8')

# Correct historical-volatility annualization by timeframe.
p=ROOT/'app/services/quant.py'; s=p.read_text(encoding='utf-8')
s=s.replace('def analyze_candles(candles: Sequence[dict]) -> dict:','def analyze_candles(candles: Sequence[dict], annualization: int = 365) -> dict:')
s=s.replace('"historical_volatility": historical_volatility(closes),','"historical_volatility": historical_volatility(closes, annualization=annualization),')
p.write_text(s,encoding='utf-8')

# Confidence calibrates a quality estimate instead of being counted again as alpha.
(ROOT/'app/services/scoring.py').write_text('''from __future__ import annotations\n\ndef clamp(v): return max(0.0,min(100.0,float(v)))\n\ndef market_scores(metrics, regime_confidence):\n rsi=metrics.get("rsi") if metrics.get("rsi") is not None else 50; adx=metrics.get("adx") or 0; mom=metrics.get("momentum_14") or 0; trend=metrics.get("trend_alignment") or 0; atr=metrics.get("atr_pct") or 0\n over=(10 if rsi>=78 or rsi<=22 else 0)+(8 if abs(mom)>=16 else 0)\n technical=50+max(-16,min(16,mom*1.6))+(7 if 42<=rsi<=67 else -4 if rsi>72 or rsi<28 else 0)-over\n strength=min(14,adx/2.8); trend_score=50+trend*15+(strength if trend>0 else -strength*.75 if trend<0 else 0)\n volatility=80 if .45<=atr<=3.8 else 62 if atr<5.5 else 35\n market=technical*.36+trend_score*.39+volatility*.25\n return {"market":clamp(market),"technical":clamp(technical),"trend":clamp(trend_score),"volatility":clamp(volatility),"confidence":clamp(regime_confidence)}\n\ndef overall_score(*,base,compatibility,performance,risk_score,capital_efficiency,news_sentiment,confidence):\n vals={"market":base["market"],"technical":base["technical"],"trend":base["trend"],"volatility":base["volatility"],"compatibility":compatibility,"performance":performance,"capital_efficiency":capital_efficiency}\n w={"market":.20,"technical":.15,"trend":.13,"volatility":.08,"compatibility":.26,"performance":.12,"capital_efficiency":.06}\n raw=sum(vals[k]*w[k] for k in w); trust=.45+.55*clamp(confidence)/100; value=50+(raw-50)*trust\n if news_sentiment<45: value-=min(8,(45-news_sentiment)*.18)\n value-=max(0,risk_score-40)*.30\n return round(clamp(value),1)\n''',encoding='utf-8')

# True 15m/1H/4H/1D fusion; 1D+4H dominate regime, shorter TFs contribute timing.
p=ROOT/'app/services/analysis.py'; s=p.read_text(encoding='utf-8')
s=s.replace('from app.domain import ACTION_ES, BotStatus, BotType, RecommendationAction','from app.domain import ACTION_ES, BotStatus, BotType, RecommendationAction, MarketRegime')
p.write_text(s,encoding='utf-8')
analysis='''async def analyze_pair(pair: str) -> dict:\n    tf_data=await market_service.all_timeframes(pair); analyzed={}; source_set=set(); is_demo=False; freshness=[]\n    annual={"15m":365*24*4,"1H":365*24,"4H":365*6,"1D":365}\n    for tf,result in tf_data.items():\n        m=analyze_candles(result.candles,annualization=annual[tf]); regime,rc=classify_regime(m)\n        analyzed[tf]={"metrics":m,"regime":str(regime),"regime_confidence":rc,"candles":result.candles,"source":str(result.source),"source_url":result.source_url,"fetched_at":result.fetched_at,"warning":result.warning}\n        source_set.add(str(result.source)); is_demo=is_demo or result.is_demo; freshness.append(result.fetched_at)\n    primary=analyzed["4H"]; daily=analyzed["1D"]; blended=dict(primary["metrics"])\n    for key in ("rsi","adx","atr_pct","historical_volatility","momentum_14","volume_change_pct","trend_alignment"):\n        vals=[(TIMEFRAME_WEIGHTS[tf],analyzed[tf]["metrics"].get(key)) for tf in TIMEFRAME_WEIGHTS]; vals=[(w,float(v)) for w,v in vals if v is not None]\n        if vals: blended[key]=sum(w*v for w,v in vals)/sum(w for w,_ in vals)\n    bvals=[(TIMEFRAME_WEIGHTS[tf],(analyzed[tf]["metrics"].get("bollinger") or {}).get("width_pct")) for tf in TIMEFRAME_WEIGHTS]; bvals=[(w,float(v)) for w,v in bvals if v is not None]\n    if bvals:\n        blended["bollinger"]=dict(primary["metrics"].get("bollinger") or {}); blended["bollinger"]["width_pct"]=sum(w*v for w,v in bvals)/sum(w for w,_ in bvals)\n    tf_scores={tf:market_scores(analyzed[tf]["metrics"],analyzed[tf]["regime_confidence"]) for tf in TIMEFRAME_WEIGHTS}\n    scores={k:sum(TIMEFRAME_WEIGHTS[tf]*tf_scores[tf][k] for tf in TIMEFRAME_WEIGHTS) for k in ("market","technical","trend","volatility")}\n    bull={"Weak Bullish","Bullish","Strong Bullish","Breakout"}; bear={"Weak Bearish","Bearish","Strong Bearish","Breakdown"}; side={"Sideways","Sideways High Vol","Sideways Low Vol"}; votes={"bull":0.0,"bear":0.0,"side":0.0}\n    for tf,w in TIMEFRAME_WEIGHTS.items():\n        r=analyzed[tf]["regime"]; votes["bull"]+=w if r in bull else 0; votes["bear"]+=w if r in bear else 0; votes["side"]+=w if r in side else 0\n    if votes["bull"]>=.55: combined=primary["regime"] if primary["regime"] in bull else str(MarketRegime.BULLISH)\n    elif votes["bear"]>=.55: combined=primary["regime"] if primary["regime"] in bear else str(MarketRegime.BEARISH)\n    elif votes["side"]>=.55: combined=primary["regime"] if primary["regime"] in side else str(MarketRegime.SIDEWAYS)\n    else: combined=str(MarketRegime.TRANSITION)\n    agree=sum(TIMEFRAME_WEIGHTS[tf] for tf in TIMEFRAME_WEIGHTS if analyzed[tf]["regime"]==primary["regime"]); conf=sum(TIMEFRAME_WEIGHTS[tf]*analyzed[tf]["regime_confidence"] for tf in TIMEFRAME_WEIGHTS); conf=min(96,max(30,conf*.88+agree*12)); scores["confidence"]=conf\n    funding,funding_source,funding_url=await market_service.funding_rate(pair)\n    if settings.data_mode=="DEMO": news={"status":"DEMO","score":50.0,"confidence":30.0,"items":[],"warning":"Noticias omitidas en modo demostración","fetched_at":datetime.now(timezone.utc).isoformat()}\n    else: news=await news_service.for_pair(pair)\n    data_conf=60.0 if is_demo else 94.0\n    if any(v["warning"] for v in analyzed.values()): data_conf-=8\n    if news["status"]!="OK": data_conf-=4\n    return {"pair":pair,"price":primary["metrics"]["price"],"regime":combined,"regime_confidence":conf,"metrics":blended,"timeframes":{tf:{**{k:v for k,v in d.items() if k!="candles"},"scores":tf_scores[tf]} for tf,d in analyzed.items()},"scores":scores,"funding_rate":funding,"funding_source":funding_source,"funding_url":funding_url,"news":news,"source":", ".join(sorted(source_set)),"is_demo":is_demo,"data_confidence":max(25.0,data_conf),"fetched_at":max(freshness),"daily_candles":daily["candles"],"timeframe_consensus":{"bullish_weight":round(votes["bull"],2),"bearish_weight":round(votes["bear"],2),"sideways_weight":round(votes["side"],2),"exact_4h_agreement":round(agree,2)}}\n    # v1.4-multitimeframe-fusion\n'''
between('app/services/analysis.py','async def analyze_pair(pair: str) -> dict:','async def run_analysis(db: Session) -> dict:',analysis)

# Recommendation: news is risk context only; confidence no longer depends on headline availability.
p=ROOT/'app/services/recommendation.py'; s=p.read_text(encoding='utf-8')
start=s.find('def evaluate('); end=s.find('\ndef action_for_existing',start)
new_eval='''def evaluate(bot_type: BotType, state: dict, equity: float, capital: float, futures_exposure: float, performance: float = 50.0, leverage: float = 1.0) -> dict:\n    direction=_direction(state["regime"]); compat,pos,neg=compatibility_score(bot_type,state["regime"],state["metrics"],direction=direction,funding_rate=state.get("funding_rate"))\n    risk=risk_assessment(bot_type,state["regime"],state["metrics"],capital,equity,leverage=leverage,futures_exposure=futures_exposure); base=state["scores"]; confidence=min(base["confidence"],state.get("data_confidence",100)); cap_eff=72 if capital<=max(equity*.20,1) else 52\n    news=state.get("news",{}) or {}; ns=float(news.get("score",50) or 50); nc=float(news.get("confidence",30) or 30)\n    score=overall_score(base=base,compatibility=compat,performance=performance,risk_score=risk["score"],capital_efficiency=cap_eff,news_sentiment=ns,confidence=confidence)\n    risk=dict(risk); risk["reasons"]=list(risk.get("reasons",[]))\n    if nc>=45 and ns<=35:\n        sev=min(12.0,(35-ns)*.45+2); risk["score"]=round(min(100,float(risk["score"])+sev),1); score=max(0.0,round(score-min(7.0,sev*.55),1)); risk["reasons"].append(f"Evento/noticias relevantes con sentimiento muy negativo ({ns:.0f}/100).")\n        if bot_type in {BotType.FUTURES_GRID,BotType.FUTURES_DCA,BotType.SIGNAL_BOT} and risk["score"]>=settings.risk.futures_ineligible_risk: risk["eligible"]=False\n    return {"score":score,"compatibility":compat,"risk":risk,"confidence":round(confidence,1),"positive":pos,"negative":neg,"direction":direction}\n\n'''
if start<0 or end<0: raise RuntimeError('v1.4 evaluate block not found')
p.write_text(s[:start]+new_eval+s[end+1:],encoding='utf-8')

