# Dynamic conviction allocation: fewer or more bots depending on real opportunity quality; unequal weights.
(ROOT/'app/services/allocation.py').write_text('''from __future__ import annotations\nfrom app.config import settings\nfrom app.domain import BotType, RecommendationAction\nFUTURES_TYPES={BotType.FUTURES_GRID,BotType.FUTURES_DCA,BotType.SIGNAL_BOT}\n\ndef _conviction(c):\n score=float(c.get("score",0)); conf=float(c.get("confidence",0)); risk=float(c.get("risk_score",100)); quality=score*.78+(100-risk)*.22; trust=.65+.35*max(0,min(100,conf))/100; v=quality*trust\n if c.get("existing") and score>=55 and risk<72:v+=settings.risk.continuity_bonus\n return max(.1,min(100,v*float(c.get("diversification_factor",1) or 1)))\n\ndef _norm(raw,cap):\n out={k:max(0,v) for k,v in raw.items()}\n for _ in range(30):\n  t=sum(out.values()); out={k:v/t for k,v in out.items()} if t else out; excess=sum(max(0,v-cap) for v in out.values()); out={k:min(v,cap) for k,v in out.items()}; free=[k for k,v in out.items() if v<cap-1e-12]\n  if excess<=1e-12 or not free:break\n  ft=sum(out[k] for k in free)\n  for k in free:out[k]+=excess*((out[k]/ft) if ft else 1/len(free))\n t=sum(out.values()); return {k:v/t for k,v in out.items()} if t else out\n\ndef _futures(rows,w):\n fk=[c["key"] for c in rows if c["futures"]]; sk=[c["key"] for c in rows if not c["futures"]]; ft=sum(w.get(k,0) for k in fk); cap=settings.risk.max_total_futures_pct\n if ft<=cap or not sk:return w\n rel=0; scale=cap/ft if ft else 0\n for k in fk: old=w[k]; w[k]=old*scale; rel+=old-w[k]\n st=sum(w[k] for k in sk)\n for k in sk:w[k]+=rel*((w[k]/st) if st else 1/len(sk))\n return w\n\ndef allocate_100_percent(candidates,total_capital,minimums=None):\n minimums=minimums or {}\n if total_capital<=0:raise ValueError("El capital total debe ser mayor que cero")\n e=[dict(c) for c in candidates if c.get("eligible",True)]\n if not e:return {"possible":False,"reason":"No hay estrategias elegibles según las reglas de riesgo.","allocations":[]}\n for c in e:c["futures"]=BotType(c["bot_type"]) in FUTURES_TYPES;c["min_value"]=float(minimums.get((c["pair"],str(c["bot_type"])),c.get("minimum") or 0));c["conviction"]=round(_conviction(c),1)\n e.sort(key=lambda c:c["conviction"],reverse=True); top=e[0]["conviction"]; maxn=2 if total_capital<80 else 3 if total_capital<160 else 4 if total_capital<350 else settings.risk.max_recommended_bots\n sel=[]; pairs=set(); notes=[]\n for c in e:\n  if len(sel)>=maxn:break\n  if c["pair"] in pairs:continue\n  if len(sel)>=2 and (c["conviction"]<60 or top-c["conviction"]>17 or c["score"]<54):continue\n  sel.append(c);pairs.add(c["pair"])\n if len(sel)<2:\n  for c in e:\n   if c["pair"] not in pairs and not c["futures"]:sel.append(c);pairs.add(c["pair"]);notes.append("Pocas oportunidades fuertes: solo se añadió una segunda estrategia spot de menor riesgo relativo para mantener 100% invertido.");break\n # continuity guard: do not crystallize an existing bot unless replacement edge is material\n for old in [c for c in e if c.get("existing") and c.get("score",0)>=55 and c.get("risk_score",100)<72]:\n  if old in sel or old["pair"] in {x["pair"] for x in sel}:continue\n  fresh=[x for x in sel if not x.get("existing")]\n  if not fresh:continue\n  weak=min(fresh,key=lambda x:x["conviction"]); required=settings.risk.min_switch_advantage+(2 if (old.get("floating_pnl") or 0)<0 else 0)\n  if weak["conviction"]-old["conviction"]<required:sel.remove(weak);sel.append(old);notes.append(f"Se mantuvo {old['pair']} porque el reemplazo no superó el umbral de cambio.")\n def solve(rows):\n  if len(rows)==1:return {rows[0]["key"]:1.0}\n  low=min(c["conviction"] for c in rows); raw={c["key"]:max(1,c["conviction"]-(low-8))**2 for c in rows}; return _futures(rows,_norm(raw,settings.risk.max_single_bot_pct))\n for _ in range(8):\n  w=solve(sel); bad=[c for c in sel if (c["min_value"]>0 and w[c["key"]]*total_capital<c["min_value"]) or (len(sel)>2 and w[c["key"]]<.10)]\n  if not bad:break\n  keys={c["key"] for c in bad};sel=[c for c in sel if c["key"] not in keys]\n  if len(sel)<2:\n   for c in e:\n    if c["key"] not in {x["key"] for x in sel} and c["pair"] not in {x["pair"] for x in sel} and not c["futures"]:sel.append(c);break\n w=solve(sel); out=[]; running=0\n for i,c in enumerate(sorted(sel,key=lambda x:x["conviction"],reverse=True)):\n  amount=round(total_capital-running,2) if i==len(sel)-1 else round(total_capital*w[c["key"]],2); running+=0 if i==len(sel)-1 else amount; pct=amount/total_capital*100; cur=float(c.get("current_capital") or 0); delta=round(amount-cur,2)\n  action=RecommendationAction.OPEN if not c.get("existing") else RecommendationAction.HOLD if abs(delta)<=max(1,total_capital*.01) else RecommendationAction.INCREASE if delta>0 else RecommendationAction.REDUCE\n  out.append({**c,"allocation_percent":pct,"recommended_capital":amount,"change":delta,"action":str(action)})\n if out:out[-1]["allocation_percent"]+=100-sum(x["allocation_percent"] for x in out)\n return {"possible":True,"total_capital":round(total_capital,2),"allocated_capital":round(sum(x["recommended_capital"] for x in out),2),"reserve":0.0,"allocation_percent":round(sum(x["allocation_percent"] for x in out),8),"allocations":out,"futures_percent":round(sum(x["allocation_percent"] for x in out if x["futures"]),4),"selected_bot_count":len(out),"selection_notes":notes,"allocation_method":"Número dinámico de bots + convicción ajustada por riesgo/confianza + concentración y continuidad controladas."}\n''',encoding='utf-8')

# Public analysis: time-normalized bot performance, stronger correlation penalty and concrete DCA/Grid parameters.
p=ROOT/'app/services/public_analysis.py'; s=p.read_text(encoding='utf-8')
s=s.replace('out[pair] = round(max(0.75, 1.0 - max(0.0, avg - 0.50) * 0.50), 4)','out[pair] = round(max(0.68, 1.0 - max(0.0, avg - 0.40) * 0.62), 4)')
old='''def _performance_from_bot(bot) -> float:\n    roi = getattr(bot, "roi", None)\n    if roi is None: return 50.0\n    return max(20.0, min(90.0, 50 + float(roi) * 2.5))\n'''
new='''def _performance_from_bot(bot) -> float:\n    roi=getattr(bot,"roi",None)\n    if roi is None:return 50.0\n    roi=float(roi); days=30.0; start=getattr(bot,"start_date",None)\n    if start is not None:\n        try:\n            if start.tzinfo is None:start=start.replace(tzinfo=timezone.utc)\n            days=max(7.0,(datetime.now(timezone.utc)-start).total_seconds()/86400)\n        except Exception:pass\n    monthly=max(-15,min(15,roi*30/days)); score=50+monthly*2+max(-8,min(8,roi*.35)); floating=getattr(bot,"floating_pnl",None); current=float(getattr(bot,"current_capital",0) or 0)\n    if floating is not None and current>0:score+=max(-8,min(4,(float(floating)/current*100)*.35))\n    return max(20,min(90,score))\n\ndef _suggested_configuration(bot_type,state):\n    m=state.get("metrics",{}) or {}; atr=max(.2,float(m.get("atr_pct") or 1.5)); price=float(state.get("price") or m.get("price") or 0); st=m.get("structure") or {}; support=st.get("support"); resistance=st.get("resistance")\n    if bot_type==BotType.SPOT_DCA:\n        step=max(1.5,min(5,atr*.9)); mult=1.28; n=5 if state.get("regime") not in {"Strong Bearish","Breakdown"} else 4; coverage=sum(step*(mult**i) for i in range(n))\n        return {"initial_order_pct":20,"safety_order_pct":12,"max_safety_orders":n,"price_step_pct":round(step,2),"step_multiplier":mult,"amount_multiplier":1.20,"take_profit_pct":round(max(1.5,min(3.5,atr*.75)),2),"estimated_price_coverage_pct":round(coverage,1),"note":"Propuesta dinámica; validar mínimos y rango en OKX."}\n    if bot_type in {BotType.SPOT_GRID,BotType.FUTURES_GRID}:\n        lower=float(support) if support else price*(1-max(.05,atr*3/100)); upper=float(resistance) if resistance else price*(1+max(.05,atr*3/100)); grids=16 if atr>=2 else 12; cfg={"lower_price":round(lower,8),"upper_price":round(upper,8),"grids":grids,"spacing":"geometric","note":"Rango propuesto desde estructura y volatilidad; revisar beneficio neto después de fees."}\n        if bot_type==BotType.FUTURES_GRID:cfg.update({"leverage":2,"max_portfolio_exposure_pct":20})\n        return cfg\n    if bot_type==BotType.RECURRING_BUY:return {"frequency":"daily","note":"Uso defensivo/de acumulación; no desplaza una ventaja táctica superior."}\n    if bot_type==BotType.SMART_ARBITRAGE:return {"funding_rate":state.get("funding_rate"),"note":"Solo si funding neto esperado permanece positivo después de fees."}\n    return {}\n'''
if old in s:s=s.replace(old,new,1)
s=s.replace('"timeframes": state["timeframes"], "regime": state["regime"],','"timeframes": state["timeframes"], "timeframe_consensus": state.get("timeframe_consensus",{}), "suggested_configuration": _suggested_configuration(bot_type,state), "regime": state["regime"],')
old_existing='''        candidates.append(_candidate_from_eval(key=f"existing:{bot.id}",pair=bot.pair,bot_type=bot.bot_type,ev=ev,state=state,existing=True,\n                                               current_capital=bot.current_capital,bot_id=bot.id,minimum=minimums.get((bot.pair,str(bot.bot_type)),0),\n                                               diversification_factor=diversification.get(bot.pair,1.0)))\n'''
if old_existing in s:
 s=s.replace(old_existing,'''        c=_candidate_from_eval(key=f"existing:{bot.id}",pair=bot.pair,bot_type=bot.bot_type,ev=ev,state=state,existing=True,current_capital=bot.current_capital,bot_id=bot.id,minimum=minimums.get((bot.pair,str(bot.bot_type)),0),diversification_factor=diversification.get(bot.pair,1.0))\n        c["floating_pnl"]=getattr(bot,"floating_pnl",None); candidates.append(c)\n''',1)
p.write_text(s,encoding='utf-8')

